import { useState, useEffect, useCallback } from 'react';
import useAuth from './useAuth';
import { 
  getAllEntries, 
  getFilteredEntries, 
  createEntry, 
  updateEntry, 
  deleteEntry, 
  getSummary
} from '../api/entryApi';
import { toUTC } from '../utils/dateFormatter';

const useEntries = () => {
  const { user } = useAuth();
  const [entries, setEntries] = useState([]);
  const [filteredEntries, setFilteredEntries] = useState([]);
  const [summary, setSummary] = useState({ 
    total_income: 0, 
    total_expense: 0, 
    balance: 0 
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [filters, setFilters] = useState({
    type: null,
    search: '',
    sortBy: 'date',
    sortOrder: 'desc'
  });

  // Fetch all entries
  const fetchEntries = useCallback(async () => {
    if (!user) return;
    
    try {
      setLoading(true);
      setError(null);
      
      const sortString = `${filters.sortBy},${filters.sortOrder}`;
      const data = await getAllEntries(user.username, sortString);
      
      setEntries(data);
      setFilteredEntries(data);
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to fetch entries');
    } finally {
      setLoading(false);
    }
  }, [user, filters.sortBy, filters.sortOrder]);

  // Fetch filtered entries
  const fetchFilteredEntries = useCallback(async () => {
    if (!user) return;
    
    try {
      setLoading(true);
      setError(null);
      
      const data = await getFilteredEntries(user.username, filters);
      
      setFilteredEntries(data);
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to fetch filtered entries');
    } finally {
      setLoading(false);
    }
  }, [user, filters]);

  // Fetch summary
  const fetchSummary = useCallback(async () => {
    if (!user) return;
    
    try {
      const data = await getSummary(user.username);
      setSummary(data);
    } catch (err) {
      console.error('Failed to fetch summary:', err);
    }
  }, [user]);

  // Add new entry
  const addEntry = async (entryData) => {
    if (!user) return null;
    
    try {
      setLoading(true);
      setError(null);
      
      // Format date to UTC for API
      const formattedData = {
        ...entryData,
        date: toUTC(entryData.date)
      };
      
      const newEntry = await createEntry(user.username, formattedData);
      
      // Update local state
      setEntries(prevEntries => [...prevEntries, newEntry]);
      await fetchSummary();
      
      return newEntry;
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to create entry');
      return null;
    } finally {
      setLoading(false);
    }
  };

  // Update existing entry
  const editEntry = async (entryId, entryData) => {
    if (!user) return null;
    
    try {
      setLoading(true);
      setError(null);
      
      // Format date to UTC for API
      const formattedData = {
        ...entryData,
        date: toUTC(entryData.date)
      };
      
      const updatedEntry = await updateEntry(user.username, entryId, formattedData);
      
      // Update local state
      setEntries(prevEntries => 
        prevEntries.map(entry => 
          entry.id === entryId ? updatedEntry : entry
        )
      );
      
      await fetchSummary();
      
      return updatedEntry;
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to update entry');
      return null;
    } finally {
      setLoading(false);
    }
  };

  // Remove entry
  const removeEntry = async (entryId) => {
    if (!user) return false;
    
    try {
      setLoading(true);
      setError(null);
      
      await deleteEntry(user.username, entryId);
      
      // Update local state
      setEntries(prevEntries => 
        prevEntries.filter(entry => entry.id !== entryId)
      );
      
      await fetchSummary();
      
      return true;
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to delete entry');
      return false;
    } finally {
      setLoading(false);
    }
  };

  // Apply filters
  const applyFilters = (newFilters) => {
    setFilters(prev => ({ ...prev, ...newFilters }));
  };

  // Reset filters
  const resetFilters = () => {
    setFilters({
      type: null,
      search: '',
      sortBy: 'date',
      sortOrder: 'desc'
    });
  };

  // Load entries and summary when user changes
  useEffect(() => {
    if (user) {
      fetchEntries();
      fetchSummary();
    } else {
      setEntries([]);
      setFilteredEntries([]);
      setSummary({ total_income: 0, total_expense: 0, balance: 0 });
    }
  }, [user, fetchEntries, fetchSummary]);

  // Apply filters when filters change
  useEffect(() => {
    if (filters.type || filters.search) {
      fetchFilteredEntries();
    } else {
      setFilteredEntries(entries);
    }
  }, [filters, entries, fetchFilteredEntries]);

  return {
    entries: filteredEntries,
    summary,
    loading,
    error,
    filters,
    addEntry,
    editEntry,
    removeEntry,
    applyFilters,
    resetFilters,
    refreshEntries: fetchEntries,
    refreshSummary: fetchSummary
  };
};

export default useEntries;
